def algorithm(func, dim, lb, ub, budget, rng):
    x = np.random.uniform(lb, ub, size=(1, dim))
    archive_size = 1
    for _ in range(budget - 1):
        noise = np.random.normal(size=dim)
        new_candidate = x + 0.05 * noise
        new_candidate = np.clip(new_candidate, lb, ub).reshape(1, -1)
        if func(new_candidate) < func(x):
            x = new_candidate
    return x
